// internal/distributed/proxy/httpserver/handler_v2.go lines 1904-1928
schema, err = proto.Marshal(&schemapb.CollectionSchema{
	Name: httpReq.CollectionName,
	Fields: []*schemapb.FieldSchema{
		{
			FieldID:      common.StartOfUserFieldID,
			Name:         httpReq.PrimaryFieldName,
			IsPrimaryKey: true,
			DataType:     idDataType,
			AutoID:       httpReq.AutoID,
			TypeParams:   idParams,
		},
		{
			FieldID:      common.StartOfUserFieldID + 1,
			Name:         httpReq.VectorFieldName,
			IsPrimaryKey: false,
			DataType:     schemapb.DataType_FloatVector,  // LINE 1919: HARDCODED FloatVector, ignores vectorFieldType param
			TypeParams: []*commonpb.KeyValuePair{
				{
					Key:   Dim,
					Value: strconv.FormatInt(int64(httpReq.Dimension), 10),
				},
			},
			AutoID: DisableAutoID,
		},
	},
